// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder recorder;

    function setUp() public {
        c = new airPort();
        recorder = new Recorder();
    }

    function testFuzz_property(address from, address a, address b, uint256 v, bool single) public {
        vm.assume(from != address(0));
        vm.assume(a != address(0) || b != address(0));
        if (single) {
            vm.assume(a != address(0));
            recorder.reset();
            address[] memory tos = new address[](1);
            tos[0] = a;
            c.transfer(from, address(recorder), tos, v);
            (address recFrom, address recTo, uint256 recV) = recorder.last();
            assertTrue(recFrom == from && recTo == a && recV == v);
        } else {
            vm.assume(a != address(0) && b != address(0) && a != b);
            recorder.reset();
            address[] memory tos = new address[](2);
            tos[0] = a;
            tos[1] = b;
            c.transfer(from, address(recorder), tos, v);
            (address recFrom, address recTo, uint256 recV) = recorder.last();
            assertTrue(recFrom == from && recTo == b && recV == v);
        }
    }
}

contract Recorder {
    address private _from;
    address private _to;
    uint256 private _value;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        _from = from;
        _to = to;
        _value = value;
        return true;
    }

    function last() external view returns (address, address, uint256) {
        return (_from, _to, _value);
    }

    function reset() external {
        _from = address(0);
        _to = address(0);
        _value = 0;
    }
}
